                    await btnInteraction.reply({ content: "Dados do pagamento não encontrados.", ephemeral: true });
                }
            } else {
                await btnInteraction.reply({ content: "Nenhum pagamento ativo.", ephemeral: true });
            }
        } catch (err) {
            console.error("Erro Pix Display:", err);
            await btnInteraction.reply({ content: "Erro obtendo Pix.", ephemeral: true });
        }
    }
}

